function visitOutside(target,fn){leaveFor(()=>goTo(target,fn));}
function projectDetails(key){const p=PROJECTS[key],v=s.economy,done=v.projects[key];
 const choices=done?[[key==='nursery'?'Visit the berry plants':'Visit the market',()=>visitOutside(key==='nursery'?FIXED.nursery:MARKET,()=>interact({id:key==='nursery'?'nursery':'market'}))],['Back to village fund',villageFund]]:[[`Fund this project · ${p.gold} G`,()=>{const before=v.projects[key],msg=run('project',{project:key});if(v.projects[key]&&!before)celebrate();show('Village project',msg,[[v.projects[key]?'See the project':'Back to project',()=>v.projects[key]?visitOutside(key==='nursery'?FIXED.nursery:MARKET,()=>interact({id:key==='nursery'?'nursery':'market'})):projectDetails(key)],['Back to village fund',villageFund]]);},'primary',!bakeryOpen(s)||v.gold<p.gold||s.inventory.wood<p.wood||s.inventory.stone<p.stone],['Back to village fund',villageFund]];
 show(done?(key==='nursery'?'The village nursery':'The village market'):p.name,done?(key==='nursery'?'Fresh berries grow here each day. Pick two and let the rest ripen.':'A little bustle by the road. The bakery brings an extra 4 G into the village fund each morning.'):p.benefit,choices,'OUR NEXT CHAPTER');
 if(!done)$('dialog-content').append(el('p',`Project needs: ${p.gold} G · ${p.wood} wood · ${p.stone} stone. Stored: ${v.gold} G · ${s.inventory.wood} wood · ${s.inventory.stone} stone.${!bakeryOpen(s)?' Open Mara’s bakery with your first batch of buns before starting another project.':''}`,'note'));
}
function bakeryNews(){const v=s.economy;show('Mara',missingFlour(s)&&v.flour.noticed?'Bit of a small batch today. I couldn’t find that sack for the morning orders.':v.projects.market?'That stall’s getting busy! Orin came for one bun and stayed for three.':v.fullDays?'Sold the last loaf! I’ve put a little gold in the village pot. What shall we build next?':'First customers tomorrow. I’d better dust the flour off the door handle.',[['Village fund & projects',villageFund],...(canOfferRecipe(s)?[['Anything new for the oven?',()=>reply('Mara','learnRecipe')]]:[]),['See you later.',close]]);}
function flourShelf(){const f=s.economy.flour;
 if(!bakeryOpen(s)){show('The kitchen shelf','A tied flour sack, tucked beside Mara’s mixing bowls. She’s still getting the kitchen ready.');return;}
 if(hasFlour(s)){show('The kitchen shelf','There’s a space beside the bowls. You have a flour sack in your basket.',[['Put the sack on the shelf',()=>{const noticed=f.noticed;toast(run('returnFlour'));close();if(noticed)show('Mara','There we go. A full batch tomorrow. Thanks for sorting that out.',[['See you in the morning.',close]]);}],...(f.state==='held'?[[`Bake simple rolls · use the sack`,()=>{toast(run('simpleRolls'));close();}]]:[]),['Leave it for now.',close]]);return;}
 if(f.state==='used'){show('The kitchen shelf','The sack in your basket is empty.',[['Talk to Mara',flourConversation],['Find Orin’s mill delivery',findMillFlour],['Leave it for now.',close]]);return;}
 show('The kitchen shelf','A tied sack beside the bowls. “Morning orders” is written on the tag.',f.state==='shelf'?[['Pick up the sack',()=>{toast(run('takeFlour'));close();}],['Ask Mara about the flour',()=>reply('Mara','askFlour')],['Leave it here.',close]]:[['Ask Mara about the flour',()=>reply('Mara','askFlour')],['Leave it here.',close]]);
}
function findMillFlour(){leaveFor(()=>approachNpc('orin',millDelivery));}
function millDelivery(){show('Orin','The mill can swap a fresh sack for two carrots. Bring them over when they’re ready.',[['Swap two carrots for flour',()=>reply('Orin','tradeFlour')],['Another time.',close]]);}
function flourConversation(){const f=s.economy.flour;
 if(!missingFlour(s)){bakeryNews();return;}
 const text=f.noticed?'Bit of a small batch today. I couldn’t find that sack for the morning orders.':'Oh, that sack? I’d set it aside for the morning orders.';
 show('Mara',text,[...(hasFlour(s)?[['I’ve got it. I’ll bring it back.',()=>show('Mara','Pop it on the shelf when you’re ready. Then I can get the full batch going.',[['Go to the flour shelf',()=>{if(s.room==='bakery'){close();goTo({x:3,y:10},flourShelf);}else{close();toast('The flour shelf is inside Mara’s kitchen.');}}],['I’ll be back.',close]])]]:[['I used it. Where can I get more?',()=>show('Mara','Orin’s got a delivery from the mill. Two carrots for a sack, he said. Could you put a fresh one on the shelf?', [['Find Orin',findMillFlour],['I’ll grow some carrots first.',close]])]]),['Can we chat about something else?',()=>smallTalk('mara')],['I’ll pop back.',close]]);
}

function walkToDoor(target,onExit=null){stop();afterDoor=onExit;if(s.player.x===target.x&&s.player.y===target.y){const id=doorAt(s,target),onward=afterDoor;afterDoor=null;if(id){enter(id);onward?.();}return;}path=route(s,s.player,target);if(!path.length){afterDoor=null;toast('There isn’t a clear route to that doorway.');}canvas.focus({preventScroll:true});}
function leaveFor(fn){close();if(s.room==='outside')fn();else walkToDoor({x:8,y:12},fn);}
